"""Ten full mock papers for semester 2 (units 5-7), in the format of the official half-year trial of
19 May 2026: 30 items / 90 minutes, U5 (integration) items 1-16, U6 (vectors) items 17-25, U7 (statistics)
items 26-30. Papers 6-10 are appended after 1-5 so the seeded answer positions of papers 1-5 never change
(students' saved attempts refer to them)."""
from qb import build_mock
from s2_papers_1_5 import P1, P2, P3, P4, P5
from s2_papers_6_10 import P6, P7, P8, P9, P10

papers = [dict(id='s2-m1', model=1, title='النموذج (1)', minutes=90, questions=P1),
          dict(id='s2-m2', model=2, title='النموذج (2)', minutes=90, questions=P2),
          dict(id='s2-m3', model=3, title='النموذج (3)', minutes=90, questions=P3),
          dict(id='s2-m4', model=4, title='النموذج (4)', minutes=90, questions=P4),
          dict(id='s2-m5', model=5, title='النموذج (5)', minutes=90, questions=P5)]
papers += [dict(id=f's2-m{n_}', model=n_, title=f'النموذج ({n_})', minutes=90, questions=qs_)
           for n_, qs_ in enumerate([P6, P7, P8, P9, P10], start=6)]

